662	  // Runtime command handlers keep the validate() middleware in the chain.
663	  // assertCanManageExecutionWorkspaceRuntimeServices still uses the Express
664	  // Request directly; call it in an Express middleware wrapper before the Handler.
665	  router.post(
666	    "/execution-workspaces/:id/runtime-services/:action",
667	    validate(workspaceRuntimeControlTargetSchema),
668	    async (req, _res, next) => {
669	      try {
670	        await assertCanManageExecutionWorkspaceRuntimeServices(db, req, {
671	          companyId: (await svc.getById(req.params.id as string))?.companyId ?? "",
672	          executionWorkspaceId: req.params.id as string,
673	          sourceIssueId: (await svc.getById(req.params.id as string))?.sourceIssueId ?? null,
674	        });
675	        next();
676	      } catch (err) {
677	        next(err);
678	      }
679	    },
680	    expressHandler(handleRuntimeCommand, adapterDeps),
681	  );
