687	        await assertCanManageExecutionWorkspaceRuntimeServices(db, req, {
688	          companyId: (await svc.getById(req.params.id as string))?.companyId ?? "",
689	          executionWorkspaceId: req.params.id as string,
690	          sourceIssueId: (await svc.getById(req.params.id as string))?.sourceIssueId ?? null,
691	        });
692	        next();
693	      } catch (err) {
694	        next(err);
695	      }
696	    },
697	    expressHandler(handleRuntimeCommand, adapterDeps),
698	  );
699	
